/**
 * Generates docs/COMMANDS.md from the live registry so command docs can never go stale.
 * Run: npm run docs
 */
import fs from 'node:fs';
import { Registry } from '../src/core/registry.js';
import { allModules } from '../src/modules/index.js';

const reg = new Registry();
allModules.forEach((m) => reg.register(m));

const lines: string[] = [
  '# Command & filter reference',
  '',
  '> AUTO-GENERATED by `npm run docs` — do not edit by hand. Edit the module source and regenerate.',
  '> "Default role" can be changed at runtime by the owner (`.setrole`, `.superfeatures`, `.userfeatures`).',
  '',
];

for (const m of reg.modules) {
  lines.push(`## Module: \`${m.name}\``, '', m.description, '');
  if (m.commands?.length) {
    lines.push('| Command | Aliases | Default role | Scope | What it does | Usage |', '|---|---|---|---|---|---|');
    for (const c of m.commands) {
      const scope = [c.groupOnly && 'group', c.privateOnly && 'private', c.needsBotAdmin && 'bot must be admin', c.ownerLocked && '🔒locked'].filter(Boolean).join(', ') || 'any';
      lines.push(`| \`${c.name}\` | ${(c.aliases ?? []).map((a) => `\`${a}\``).join(' ') || '—'} | ${c.defaultRole} | ${scope} | ${c.description} | \`${c.usage ?? c.name}\` |`);
    }
    lines.push('');
  }
  if (m.filters?.length) {
    lines.push('| Filter | Priority | What it does |', '|---|---|---|');
    for (const f of m.filters) lines.push(`| \`${f.name}\` | ${f.priority} | ${f.description} |`);
    lines.push('');
  }
  if (m.onGroupParticipants) lines.push('_Also reacts to group join/leave events._', '');
}

lines.push('## Feature keys (what `.setrole` / `.perms` use)', '', '| Feature | Default role | Commands |', '|---|---|---|');
for (const f of reg.features()) lines.push(`| \`${f.feature}\` | ${f.defaultRole}${f.locked ? ' 🔒' : ''} | ${f.commands.map((c) => `\`${c}\``).join(' ')} |`);

fs.writeFileSync(new URL('../docs/COMMANDS.md', import.meta.url), lines.join('\n') + '\n');
console.log(`docs/COMMANDS.md written (${reg.commands.length} commands, ${reg.filters.length} filters)`);
